import{_ as e,o as t,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"学习路线图","description":"从 TypeScript 与 Node.js 工程基础出发，逐步掌握模型、Agent、NestJS、RAG、LangGraph 和全栈交付","frontmatter":{"title":"学习路线图","description":"从 TypeScript 与 Node.js 工程基础出发，逐步掌握模型、Agent、NestJS、RAG、LangGraph 和全栈交付","article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/learning/learning-roadmap.md","filePath":"ts-ai/appendix/learning/learning-roadmap.md","lastUpdated":1786166505000}'),r={name:"ts-ai/appendix/learning/learning-roadmap.md"};function i(l,a,o,p,d,c){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="学习路线图" tabindex="-1">学习路线图 <a class="header-anchor" href="#学习路线图" aria-label="Permalink to &quot;学习路线图&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>TS-AI 全栈开发不是把 LangChain.js、NestJS、Nuxt 和向量数据库分别学一遍，再尝试把它们拼在一起。更可靠的顺序是先跑通模型调用和数据契约，再增加工具、状态、服务端、知识库与前端交互，最后补齐评测、安全和运维闭环。</p><p>本路线最终希望你能够独立完成下面这条结果链：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理解需求与风险边界</span></span>
<span class="line"><span>→ 选择普通函数、Chain、Workflow 或 Agent</span></span>
<span class="line"><span>→ 接入模型、工具、RAG 与记忆</span></span>
<span class="line"><span>→ 使用 NestJS 提供可靠服务</span></span>
<span class="line"><span>→ 使用 Nuxt 构建可恢复的流式交互</span></span>
<span class="line"><span>→ 测试、评测、观测和保护系统</span></span>
<span class="line"><span>→ 部署、验收并持续迭代</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>路线图只回答“先学什么、做到什么程度再继续”。</p><ul><li><strong>会 Vue 3 / TypeScript、几乎没写过后端：</strong> 优先使用裁剪版 <a href="/ts-ai/appendix/learning/frontend-backend-learning-path">前端出身学习路线（Vue/TS → Nest）</a>，不要第一遍按阶段 0–8 全量推进。</li><li>需要逐项检查具体知识时，使用<a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a>（清单是查漏工具，不是第一遍必勾满）。</li><li>需要查某个框架的对象和方法时，进入 <a href="/ts-ai/appendix/api-index/">API 索引</a>。</li></ul><h2 id="这张路线图如何使用" tabindex="-1">这张路线图如何使用 <a class="header-anchor" href="#这张路线图如何使用" aria-label="Permalink to &quot;这张路线图如何使用&quot;">​</a></h2><h3 id="前置知识边界" tabindex="-1">前置知识边界 <a class="header-anchor" href="#前置知识边界" aria-label="Permalink to &quot;前置知识边界&quot;">​</a></h3><p>本手册不重复讲完整的 JavaScript、TypeScript 和 Node.js 语言课程。开始主线前，应至少具备以下能力：</p><table tabindex="0"><thead><tr><th>能力</th><th>最低要求</th><th>需要补学时</th></tr></thead><tbody><tr><td>JavaScript 异步</td><td>能解释 Promise、<code>async</code>/<code>await</code>、异常传播和并发等待</td><td><a href="/frontend/guide/core/javascript/async-programming">Promise 与异步编程</a></td></tr><tr><td>TypeScript 类型</td><td>能定义对象、函数、联合类型和泛型，并完成类型收窄</td><td><a href="/frontend/guide/core/typescript/">TypeScript 类型系统</a></td></tr><tr><td>运行时校验</td><td>知道 TypeScript 类型不会在运行时自动校验外部输入</td><td><a href="/frontend/guide/core/typescript/runtime-validation">运行时类型校验</a></td></tr><tr><td>模块与依赖</td><td>能使用 ESM、包管理器、环境变量和项目脚本</td><td><a href="/frontend/guide/engineering/server/node-modules">Node.js 模块与包执行</a></td></tr><tr><td>Node.js 运行时</td><td>能区分进程、事件循环、I/O 与浏览器运行环境</td><td><a href="/frontend/guide/engineering/server/node-runtime">Node.js 运行时与应用边界</a></td></tr><tr><td>HTTP 与流</td><td>理解请求响应、状态码、SSE 与取消的基本含义</td><td><a href="/frontend/guide/core/web/network/http">HTTP 语义与版本</a></td></tr></tbody></table><p>如果无法判断自己缺少什么，先完成 <a href="/ts-ai/foundations/getting-started/agent-prerequisites-map">Agent 开发前置知识地图</a>。不需要等到 TypeScript 的高级类型全部学完，只要能够理解示例、修改类型并定位编译错误，就可以进入模型主线。</p><h3 id="三层掌握标准" tabindex="-1">三层掌握标准 <a class="header-anchor" href="#三层掌握标准" aria-label="Permalink to &quot;三层掌握标准&quot;">​</a></h3><p>每个阶段都按三个层次验收：</p><ol><li><strong>能解释</strong>：能说明概念解决什么问题、与相邻概念有什么边界。</li><li><strong>能实现</strong>：不照抄完整答案也能写出最小可运行版本。</li><li><strong>能验证</strong>：能观察输入、输出、状态或 Trace，并覆盖至少一个失败分支。</li></ol><p>只看完文章属于“接触过”，不属于“掌握”。路线图中的“通过标准”满足后，再进入下一阶段。</p><h2 id="完整学习主线" tabindex="-1">完整学习主线 <a class="header-anchor" href="#完整学习主线" aria-label="Permalink to &quot;完整学习主线&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段 0  TypeScript、Node.js 与 HTTP 前置能力</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>阶段 1  模型基础与第一次 LangChain.js 调用</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>阶段 2  LangChain.js、工具、MCP 与 Agent Runtime</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>阶段 3  NestJS AI 服务、实时 API、数据与任务</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>阶段 4  RAG、检索与记忆</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>阶段 5  LangGraph.js、持久执行与多 Agent</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>阶段 6  Nuxt AI 交互与全栈协议</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>阶段 7  测试、评测、安全、观测与部署</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>阶段 8  架构决策、完整项目与交付</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p>这是一条依赖顺序，不是要求把每个模块一次性学到最深。阶段 4 和阶段 5 可以根据项目需求调整先后，但在学习 LangGraph.js 或多 Agent 之前，必须先完成单 Agent、工具调用和状态边界。</p><h3 id="阶段-0-补齐工程前置能力" tabindex="-1">阶段 0：补齐工程前置能力 <a class="header-anchor" href="#阶段-0-补齐工程前置能力" aria-label="Permalink to &quot;阶段 0：补齐工程前置能力&quot;">​</a></h3><p><strong>学习目标</strong>：能够创建并调试一个 TypeScript Node.js 项目，理解外部输入为什么需要运行时校验。</p><p><strong>学习顺序</strong>：</p><ol><li>根据<a href="/ts-ai/foundations/getting-started/agent-prerequisites-map">前置知识地图</a>定位缺口。</li><li>完成<a href="/ts-ai/foundations/getting-started/create-typescript-ai-project">创建 TypeScript AI 项目</a>，确认开发、构建和测试命令都能运行。</li><li>学习 <a href="/ts-ai/foundations/getting-started/zod-minimum-introduction">Zod 最小入门</a>，建立“静态类型 + 运行时 Schema”的双重数据边界。</li></ol><p><strong>实践产物</strong>：一个能够读取环境变量、校验 JSON 输入、运行测试并输出结构化日志的最小项目。</p><p><strong>通过标准</strong>：能够解释 <code>tsconfig</code>、ESM、环境变量和 Zod 分别在哪个阶段生效；输入缺字段或类型错误时，程序能返回可观察的失败结果。</p><h3 id="阶段-1-理解模型并跑通最小调用" tabindex="-1">阶段 1：理解模型并跑通最小调用 <a class="header-anchor" href="#阶段-1-理解模型并跑通最小调用" aria-label="Permalink to &quot;阶段 1：理解模型并跑通最小调用&quot;">​</a></h3><p><strong>学习目标</strong>：把模型当成具有请求、响应、限制和失败模式的外部服务，而不是会自动给出正确答案的函数。</p><p><strong>学习顺序</strong>：</p><ol><li>完成<a href="/ts-ai/foundations/model/">模型基础</a>中的 Token、上下文、消息、采样、结构化输出、模型选型和安全边界。</li><li>按顺序实践第一次 <code>ChatOpenAI.invoke()</code>、<code>PromptTemplate</code>、Message 和 Zod 结构化输出。</li><li>使用 Fake 或 Mock 覆盖正常响应、超时、限流和解析失败，具体见<a href="/ts-ai/foundations/langchain-bridge/">最小实践</a>。</li></ol><p><strong>实践产物</strong>：一个接收业务输入、调用模型并返回经过 Zod 校验结果的小程序，同时具备不访问真实模型的测试。</p><p><strong>通过标准</strong>：能够从日志中指出请求消息、模型配置、响应内容、用量和失败原因；知道模型能力、供应商 API 与 LangChain.js 封装不是同一层。</p><h3 id="阶段-2-掌握-langchain-js-与单-agent" tabindex="-1">阶段 2：掌握 LangChain.js 与单 Agent <a class="header-anchor" href="#阶段-2-掌握-langchain-js-与单-agent" aria-label="Permalink to &quot;阶段 2：掌握 LangChain.js 与单 Agent&quot;">​</a></h3><p><strong>学习目标</strong>：理解 LangChain.js 的核心抽象，并构建具有受控工具、上下文和停止条件的单 Agent。</p><p><strong>学习顺序</strong>：</p><ol><li>学习 <a href="/ts-ai/agent/langchain-core/">LangChain.js 核心</a>：ChatModel、Message、PromptTemplate、Runnable 以及 <code>invoke</code>、<code>batch</code>、<code>stream</code>。</li><li>学习<a href="/ts-ai/agent/models-output/">模型与输出</a>：模型参数、Parser、结构化输出、上下文预算和模型回退。</li><li>学习<a href="/ts-ai/agent/tools-mcp/">工具与 MCP</a>：Schema、Tool Call、ToolMessage、超时、错误、可信 Context 和 MCP 集成。</li><li>学习 <a href="/ts-ai/agent/runtime/">Agent Runtime</a>：<code>createAgent</code>、State、Context、Middleware、Guardrails、流式事件和 Agent 模式边界。</li></ol><p><strong>实践产物</strong>：一个可以查询只读业务数据并输出结构化结果的 Agent。工具必须有明确 Schema、权限边界、超时处理和测试替身。</p><p><strong>通过标准</strong>：能够完整展示“用户消息 → 模型决策 → 工具调用 → ToolMessage → 最终输出”的轨迹；能说明为什么这里需要 Agent，而不是普通函数或固定 Runnable。</p><h3 id="阶段-3-构建-nestjs-ai-服务" tabindex="-1">阶段 3：构建 NestJS AI 服务 <a class="header-anchor" href="#阶段-3-构建-nestjs-ai-服务" aria-label="Permalink to &quot;阶段 3：构建 NestJS AI 服务&quot;">​</a></h3><p><strong>学习目标</strong>：把模型和 Agent 代码放入边界清晰、可以测试和演进的服务端应用，而不是直接堆在 Controller 中。</p><p><strong>学习顺序</strong>：</p><ol><li>通过 <a href="/ts-ai/backend/nestjs-core/">NestJS 核心</a>掌握 Module、Provider、依赖注入、作用域和请求管道；先跑通<a href="/ts-ai/backend/nestjs-core/minimal-agent-api-skeleton">最小可运行 Agent API</a>（能用 <code>curl</code> 打通鉴权失败与同步 Run）。</li><li>在 <a href="/ts-ai/backend/ai-service/">AI 服务架构</a>中组织 Model Gateway、Agent Module、Tool Registry、Prompt 配置和租户 Context。</li><li>在 <a href="/ts-ai/backend/api-realtime/">API 与实时通信</a>中完成 REST、SSE、WebSocket、文件上传和 OpenAPI 契约。</li><li>在<a href="/ts-ai/backend/data-tasks/">数据与任务</a>中区分 Thread、Run、Message、业务数据、Redis 状态和 BullMQ 任务。</li></ol><p><strong>实践产物</strong>：一个包含 REST 创建 Run、SSE 推送事件、DTO 校验、统一错误格式和可取消长任务的 NestJS 服务。</p><p><strong>通过标准</strong>：能够指出请求 Context、Agent State、Checkpoint、缓存和业务数据库分别由谁拥有；断开连接、重复请求或 Worker 重启时不会悄悄产生重复副作用。</p><h3 id="阶段-4-加入-rag-与记忆" tabindex="-1">阶段 4：加入 RAG 与记忆 <a class="header-anchor" href="#阶段-4-加入-rag-与记忆" aria-label="Permalink to &quot;阶段 4：加入 RAG 与记忆&quot;">​</a></h3><p><strong>学习目标</strong>：构建从原始文档到带来源回答的完整知识链，并把长期记忆与普通对话上下文分开管理。</p><p><strong>学习顺序</strong>：</p><ol><li>从 <a href="/ts-ai/knowledge/rag-foundations/">RAG 基础</a>弄清原理边界，并跑通<a href="/ts-ai/knowledge/rag-foundations/minimal-rag-skeleton">最小可运行 RAG</a>。</li><li>从<a href="/ts-ai/knowledge/document-processing/">文档处理</a>完成加载、清洗、元数据、Chunk、Ingestion 和增量更新。</li><li>在<a href="/ts-ai/knowledge/retrieval/">检索系统</a>中学习 Embedding、pgvector、过滤、混合检索、Reranker、权限与检索评测。</li><li>在 <a href="/ts-ai/knowledge/rag-engineering/">LangChain.js RAG</a>中连接 Document、Retriever、RAG Chain、上下文、引用和流式回答。</li><li>按需学习<a href="/ts-ai/knowledge/advanced-rag/">高级 RAG</a>（进阶），不要一开始就使用 Agentic RAG 或 GraphRAG。</li><li>在<a href="/ts-ai/knowledge/memory/">记忆系统</a>中处理短期状态、长期事实、Checkpoint、Store、更新删除和租户隔离，最后用<a href="/ts-ai/knowledge/assembly/assembly-recipes-checklist">组装配方与自检</a>收束。</li></ol><p><strong>实践产物</strong>：一个支持文件上传、增量索引、权限过滤、带来源回答和知识不足拒答的 RAG 服务，并拥有独立的检索测试集。</p><p><strong>通过标准</strong>：能够展示原始文档、Chunk、索引记录、召回结果、最终上下文和引用答案；能分别验证检索质量与生成质量，也能删除某个用户的长期记忆。</p><h3 id="阶段-5-使用-langgraph-js-管理复杂流程" tabindex="-1">阶段 5：使用 LangGraph.js 管理复杂流程 <a class="header-anchor" href="#阶段-5-使用-langgraph-js-管理复杂流程" aria-label="Permalink to &quot;阶段 5：使用 LangGraph.js 管理复杂流程&quot;">​</a></h3><p><strong>学习目标</strong>：在 Agent 循环之外显式管理状态、路由、持久化、恢复和人工介入。</p><p><strong>学习顺序</strong>：</p><ol><li>从 <a href="/ts-ai/workflow/workflow-foundations/">工作流基础</a>弄清与 Chain/Agent 的边界，并跑通<a href="/ts-ai/workflow/workflow-foundations/minimal-stategraph-skeleton">最小可运行 StateGraph</a>。</li><li>学习 <a href="/ts-ai/workflow/langgraph-core/">LangGraph.js 核心</a>中的建模、StateGraph、Reducer、Node、Edge、条件路由、并行和 Subgraph。</li><li>学习<a href="/ts-ai/workflow/durable-execution/">持久执行</a>中的 Checkpoint、Store、Interrupt、Command、暂停恢复、幂等和状态迁移（Interrupt API 与暂停场景分篇阅读）。</li><li>使用<a href="/ts-ai/workflow/workflow-quality/">工作流质量</a>验证状态转换、终止条件、Trace、队列集成（图 Job ≠ <code>agent-run</code>）和版本兼容。</li><li>只有单 Agent 或固定单图确实无法满足职责隔离时，再进入<a href="/ts-ai/workflow/multi-agent/">多 Agent</a>（进阶）。</li><li>用<a href="/ts-ai/workflow/assembly/assembly-recipes-checklist">组装配方与自检</a>收束。</li></ol><p><strong>实践产物</strong>：一个需要人工审批的业务工作流，能够在进程重启后恢复，并对重复恢复和外部副作用提供幂等保护。</p><p><strong>通过标准</strong>：能够从执行轨迹证明每个节点的输入、输出和路由选择；循环存在明确预算与终止条件；多 Agent 方案有单 Agent 或固定工作流基线可比较。</p><h3 id="阶段-6-完成-nuxt-全栈交互" tabindex="-1">阶段 6：完成 Nuxt 全栈交互 <a class="header-anchor" href="#阶段-6-完成-nuxt-全栈交互" aria-label="Permalink to &quot;阶段 6：完成 Nuxt 全栈交互&quot;">​</a></h3><p><strong>学习目标</strong>：让前端准确呈现 Run 的生命周期、流式事件、工具确认、长任务和错误状态，而不是只显示逐字追加的文本。</p><p><strong>学习顺序</strong>：</p><ol><li>先在<a href="/ts-ai/integration/interaction-protocols/">交互协议</a>中定义 Message、Run、Tool Call、SSE 事件、取消、重连、鉴权和错误格式。</li><li>通过 <a href="/ts-ai/integration/ai-interaction/">AI 交互设计</a>设计流式反馈、引用、工具确认、长任务、可访问性和移动端体验。</li><li>立刻跑通<a href="/ts-ai/integration/vue-nuxt/minimal-ai-chat-ui">最小可运行 AI Chat UI</a>（假事件流），再以 <a href="/ts-ai/integration/vue-nuxt/">Vue 3 与 Nuxt</a>主线完成 Composable、状态、流式渲染与 Nest 对接；工具/上传/SSR/AI SDK 按需。</li><li><a href="/ts-ai/integration/react-next/">React 与 Next.js 扩展</a>用于选型与迁移，<strong>不是</strong> Nuxt 主线前置；入组先读选型文。</li><li>用<a href="/ts-ai/integration/assembly/assembly-recipes-checklist">组装配方与自检</a>收束。</li></ol><p><strong>实践产物</strong>：一个连接 NestJS 的 Nuxt AI Chat，支持流式消息、取消与重连、引用跳转、工具确认、文件索引状态和错误恢复。</p><p><strong>通过标准</strong>：网络断开、页面刷新、工具等待确认和后台长任务都具有明确 UI 状态；前端不会把尚未确认的流式片段当成已完成业务结果。</p><h3 id="阶段-7-建立生产质量闭环" tabindex="-1">阶段 7：建立生产质量闭环 <a class="header-anchor" href="#阶段-7-建立生产质量闭环" aria-label="Permalink to &quot;阶段 7：建立生产质量闭环&quot;">​</a></h3><p><strong>学习目标</strong>：用数据证明系统质量，并控制权限、成本、故障和发布风险。</p><p><strong>学习顺序</strong>：</p><ol><li>在<a href="/ts-ai/quality/testing-evaluation/">测试与评测</a>中先完成工程测试（单元、Mock、Nest、Nuxt E2E），再建立评测数据集与回归门禁；LangSmith 评测实验为可选。</li><li>在<a href="/ts-ai/quality/security-governance/">安全与治理</a>中处理认证、租户横切、工具权限、Prompt Injection、敏感数据；供应链按需。</li><li>在<a href="/ts-ai/quality/observability-reliability/">可观测性与可靠性</a>中按「日志 → Trace/指标 → OTel 接线 → 成本 → 限流降级 → SLO」建立观测与韧性。</li><li>在<a href="/ts-ai/quality/deployment-operations/">部署与运维</a>中先完成 Secret、容器、健康检查与挂门禁的 CI/CD；灰度、扩容与恢复为进阶。</li><li>用<a href="/ts-ai/quality/assembly/assembly-recipes-checklist">组装配方与自检</a>收束上线清单。</li></ol><p><strong>实践产物</strong>：一套可在 CI 中运行的测试与评测、一张关键指标仪表盘、一份威胁模型和一次可回滚的部署记录。</p><p><strong>通过标准</strong>：模型、工具、RAG、工作流和 UI 的失败能够被分层定位；发布前有可执行门禁；高风险工具需要授权或人工确认；故障恢复经过演练而不是停留在文档中。</p><h3 id="阶段-8-通过完整项目完成交付" tabindex="-1">阶段 8：通过完整项目完成交付 <a class="header-anchor" href="#阶段-8-通过完整项目完成交付" aria-label="Permalink to &quot;阶段 8：通过完整项目完成交付&quot;">​</a></h3><p><strong>学习目标</strong>：把知识组合成可验收项目，并能说明每个架构选择的约束、代价和替代方案。</p><p><strong>学习顺序</strong>：</p><ol><li>先阅读<a href="/ts-ai/architecture/design-decisions/">架构与决策</a>必学篇（分层、框架边界、状态所有权）；网关 ADR 与选型 ADR 按需。</li><li>根据业务<strong>选读 0～1 篇</strong> <a href="/ts-ai/architecture/agent-types/">Agent 类型</a>（Research/SQL 的模式篇，项目实战由 P3/P4 承接；Browser/Coding/Voice 为扩展）。</li><li>完成必修基线项目<a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a>：从 0 建造 7 章，章末勾验收 A1–A8；后续项目实战 P2–P5（帮助中心问答 / 研究报告 / 数据分析 / 内容审校）规划见<a href="/ts-ai/architecture/">架构与实战总览</a>。</li><li>最小基线可跑后，用<a href="/ts-ai/architecture/delivery/">项目交付</a>填写本项目的验收、评测、权限、威胁、发布与运维交接（方法外链 quality）。</li><li>用<a href="/ts-ai/architecture/assembly/assembly-recipes-checklist">组装配方与自检</a>收束。</li></ol><p><strong>实践产物</strong>：一份可按 A1–A8（或后续项目 DoD）验收的交付：架构说明、可观察的 Run/SSE 轨迹、评测与威胁记录、以及<strong>你自己维护的仓库</strong>中可启动的 web+api（项目篇是拼装/验收规格；以 README 与 compose 能被他人复现为准）。</p><p><strong>通过标准</strong>：项目不是“能够演示”就结束，而是输入输出可验证、失败可观察、权限可审计、版本可发布、故障可恢复；并留下可复查的决策记录。</p><h2 id="可裁剪路径" tabindex="-1">可裁剪路径 <a class="header-anchor" href="#可裁剪路径" aria-label="Permalink to &quot;可裁剪路径&quot;">​</a></h2><h3 id="按项目目标裁剪" tabindex="-1">按项目目标裁剪 <a class="header-anchor" href="#按项目目标裁剪" aria-label="Permalink to &quot;按项目目标裁剪&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目目标</th><th>必学路径</th><th>后续增强</th></tr></thead><tbody><tr><td>AI 客服中心（必修基线）</td><td>阶段 0 → 1 → 2 → 3 → 6 → 7 → 8</td><td>P2–P4 任一产品形态</td></tr><tr><td>P2 帮助中心问答（对外 RAG）</td><td>阶段 0 → 1 → 2 → 3 → 4 → 6 → 7 → 8</td><td>查询改写、Reranker、反馈闭环</td></tr><tr><td>P3 深度研究报告</td><td>阶段 0 → 1 → 2 → 3 → 5 → 6 → 7 → 8</td><td>长任务队列、检查点恢复</td></tr><tr><td>P4 经营数据分析</td><td>先完成客服中心，再进阶 MCP 治理与 SQL 护栏</td><td>供应链与工具 ACL</td></tr><tr><td>P5 多角色内容审校</td><td>先完成基线或 B/C/D 之一</td><td>成本与终止治理、对照实验</td></tr><tr><td>Research / SQL 模式</td><td>阶段相关能力 + <a href="/ts-ai/architecture/agent-types/">Agent 类型</a>对应篇</td><td>由 P3 / P4 项目实战承接</td></tr><tr><td>React/Next.js 项目</td><td>先完成阶段 1、2、3 和交互协议，再进入 React/Next.js 扩展</td><td>与 Nuxt 实现对照</td></tr></tbody></table><p>裁剪表示暂缓无关模块，不表示跳过质量与安全。任何会访问私有数据或执行外部操作的项目，都必须学习认证授权、工具权限、审计、超时和幂等。</p><h3 id="按已有背景选择入口" tabindex="-1">按已有背景选择入口 <a class="header-anchor" href="#按已有背景选择入口" aria-label="Permalink to &quot;按已有背景选择入口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>已有背景</th><th>建议入口</th><th>不应直接跳过</th></tr></thead><tbody><tr><td>Vue 3 前端开发（几乎无 Nest）</td><td><strong>默认走</strong> <a href="/ts-ai/appendix/learning/frontend-backend-learning-path">前端出身学习路线</a></td><td>模型失败模式、Nest 最小 API、服务端状态所有权、产品 SSE</td></tr><tr><td>Vue 3 前端开发（已会一点 Node）</td><td>阶段 0 校验后进阶段 1，阶段 3 仍按 nestjs-core「先 curl 再拆 Module」</td><td>同上</td></tr><tr><td>Node.js/NestJS 后端开发</td><td>阶段 1</td><td>结构化输出、工具契约、前端流式状态</td></tr><tr><td>Python Agent 开发</td><td>阶段 0 的 TypeScript/Zod，再进入阶段 1 和 2</td><td>LangChain.js 包边界、Node.js 异步与 NestJS 生命周期</td></tr><tr><td>只做过模型 API 调用</td><td>阶段 1 的测试部分，然后进入阶段 2</td><td>Agent 与 Chain 边界、工具副作用、评测</td></tr><tr><td>AI 与全栈均为初学者</td><td>从阶段 0 顺序完成；更建议先补 frontend 手册 TS/异步</td><td>不建议直接从多 Agent 或 GraphRAG 开始</td></tr></tbody></table><p>“用过类似框架”不能自动等于掌握当前生态。跳过某个阶段前，应先对照该阶段的通过标准，而不是只根据工作年限判断。</p><h2 id="推进与验收规则" tabindex="-1">推进与验收规则 <a class="header-anchor" href="#推进与验收规则" aria-label="Permalink to &quot;推进与验收规则&quot;">​</a></h2><h3 id="每个分组采用一个闭环" tabindex="-1">每个分组采用一个闭环 <a class="header-anchor" href="#每个分组采用一个闭环" aria-label="Permalink to &quot;每个分组采用一个闭环&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阅读知识地图</span></span>
<span class="line"><span>→ 运行最小示例</span></span>
<span class="line"><span>→ 修改一个关键参数或分支</span></span>
<span class="line"><span>→ 制造一个失败场景</span></span>
<span class="line"><span>→ 通过测试、日志或 Trace 解释结果</span></span>
<span class="line"><span>→ 将结论记录到项目中</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>建议始终维护一个贯穿项目，而不是每篇文章都新建互不相关的 Demo。项目可以从简单问答开始，逐步增加结构化输出、工具、NestJS API、RAG、工作流、Nuxt UI 和质量体系。</p><h3 id="不要用这些信号判断掌握程度" tabindex="-1">不要用这些信号判断掌握程度 <a class="header-anchor" href="#不要用这些信号判断掌握程度" aria-label="Permalink to &quot;不要用这些信号判断掌握程度&quot;">​</a></h3><ul><li>记住了大量类名和方法名。</li><li>示例运行成功过一次。</li><li>模型在演示数据上给出了看起来合理的答案。</li><li>接入了更多 Agent、工具或向量数据库。</li><li>本地能够启动，但没有测试、评测和失败记录。</li></ul><p>更可靠的证据是可重复运行的测试、固定评测集、完整执行轨迹、明确的失败输出和可复现的部署结果。</p><h2 id="完成路线后的能力证明" tabindex="-1">完成路线后的能力证明 <a class="header-anchor" href="#完成路线后的能力证明" aria-label="Permalink to &quot;完成路线后的能力证明&quot;">​</a></h2><p>完成主线后，应能拿出以下证据：</p><ul><li>一份说明为什么选择函数、Chain、Workflow 或 Agent 的架构决策记录。</li><li>一条包含模型、工具、状态与最终输出的可观察执行轨迹。</li><li>一个能够处理断线、取消、恢复和工具确认的 Nuxt 交互界面。</li><li>一个带原始文档、召回结果、最终上下文和来源引用的 RAG 结果流。</li><li>一个能够暂停、恢复、重放并保护副作用的 LangGraph.js 工作流。</li><li>一套覆盖正常路径与失败路径的测试、评测数据集和回归门禁。</li><li>一份包含权限、Prompt Injection、敏感数据和供应链风险的威胁模型。</li><li>一次包含监控、灰度、回滚和恢复验证的交付记录。</li></ul><p>接下来可以使用<a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a>查漏补缺，通过<a href="/ts-ai/appendix/references/technology-stack-compatibility">技术栈与版本兼容表</a>核对依赖，并从<a href="/ts-ai/appendix/templates/">工程模板</a>选择评测、架构、威胁模型和发布验收模板。</p>`,91)])])}const u=e(r,[["render",i]]);export{g as __pageData,u as default};
